namespace sv_bad056e379c346609cf925136c5a19cb.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["WH-001"] = "Warehouse A — East",
        ["WH-002"] = "Warehouse B — West",
        ["WH-003"] = "Warehouse C — Central",
        ["WH-004"] = "Warehouse D — South",
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

namespace sv_bad056e379c346609cf925136c5a19cb.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    private int _lastLowStockCount;
    public int LastLowStockCount => _lastLowStockCount;

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        int count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to publish a new count to all subscribers.
    /// </summary>
    public void PublishAlertCount(int count)
    {
        _lastLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

@using sv_bad056e379c346609cf925136c5a19cb.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-nowrap" for="warehousePicker">
        <strong>📦 Warehouse:</strong>
    </label>
    <select id="warehousePicker"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_bad056e379c346609cf925136c5a19cb.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LastLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2" title="Low-stock items">
        @AlertService.LastLowStockCount
    </span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2" title="No low-stock items">
        0
    </span>
}

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

