@page "/dashboard"
@rendermode InteractiveServer
@using sv_bad056e379c346609cf925136c5a19cb.Services
@using sv_bad056e379c346609cf925136c5a19cb.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            📦 @WarehouseState.CurrentWarehouseName
        </h5>
        <p class="card-text">
            Currently monitoring <strong>@WarehouseState.CurrentWarehouseId</strong>.
            Switch warehouses using the selector in the top bar.
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card text-white @(AlertService.LastLowStockCount > 5 ? "bg-danger" : AlertService.LastLowStockCount > 0 ? "bg-warning" : "bg-success")">
            <div class="card-body text-center">
                <h2 class="display-4">@AlertService.LastLowStockCount</h2>
                <p class="card-text">Low-Stock Items</p>
                <AlertBadge />
            </div>
        </div>
    </div>
    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Live Monitoring</div>
            <div class="card-body">
                <p>
                    @if (_isPolling)
                    {
                        <span class="text-success">● Polling active</span>
                        <span class="text-muted"> — refreshing every 10 seconds</span>
                    }
                    else
                    {
                        <span class="text-muted">○ Polling stopped</span>
                    }
                </p>
                @if (_lastChecked.HasValue)
                {
                    <p class="text-muted mb-0">Last checked: @_lastChecked.Value.ToString("HH:mm:ss")</p>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime? _lastChecked;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertDataRefreshed;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately
        StopPolling();
        InvokeAsync(async () =>
        {
            await PollOnce();
            StartPolling();
            StateHasChanged();
        });
    }

    private void OnAlertDataRefreshed()
    {
        InvokeAsync(StateHasChanged);
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _isPolling = true;
        _ = PollLoop(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _isPolling = false;
    }

    private async Task PollLoop(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        // Do an initial poll right away
        await PollOnce();
        await InvokeAsync(StateHasChanged);

        while (await timer.WaitForNextTickAsync(ct))
        {
            await PollOnce();
            await InvokeAsync(StateHasChanged);
        }
    }

    private async Task PollOnce()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastChecked = DateTime.Now;
        // Publish to all subscribers (sidebar badge, other components, etc.)
        AlertService.PublishAlertCount(count);
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertDataRefreshed;
    }
}

