builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped = per-circuit in Blazor Server, so each user gets independent state
builder.Services.AddScoped<sv_bad056e379c346609cf925136c5a19cb.Services.WarehouseStateService>();
builder.Services.AddScoped<sv_bad056e379c346609cf925136c5a19cb.Services.InventoryAlertService>();

